package com.example

import com.example.ExamQuestionHelper.QSpec

internal object CivicsLiveExamStateOrgBank1 {
  private const val T = "ව්‍යවස්ථාදායකය, විධායකය හා අධිකරණ ව්‍යුහය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("'බලතල බෙදීමේ න්‍යාය' විධිමත්ව ඉදිරිපත් කළ ප්‍රංශ දාර්ශනිකයා කවුද?", "මොන්ටෙස්කියු", "ජීන් ජැක් රූසෝ", "තෝමස් හොබ්ස්", "කාල් මාක්ස්", "1748 'නීතියේ ජීව ගුණය' කෘතියෙන් මොන්ටෙස්කියු බලතල බෙදීමේ න්‍යාය ප්‍රකාශ කළේය."),
    q("ආණ්ඩුවේ බලතල ප්‍රධාන වශයෙන් බෙදා වෙන් කරන ආයතන තුන මොනවාද?", "ව්‍යවස්ථාදායකය, විධායකය සහ අධිකරණය", "පොලිසිය, හමුදාව සහ රේගුව", "පළාත් සභා, නගර සභා සහ ගම්සභා", "මහ බැංකුව, භාණ්ඩාගාරය සහ තැපෑල", "නීති සම්පාදනය, ක්‍රියාත්මක කිරීම හා අර්ථනිරූපණය යන අංශ තුන මෙලෙස වෙන් කෙරේ."),
    q("මොන්ටෙස්කියුගේ බලතල බෙදීමේ න්‍යායේ ප්‍රධානතම අරමුණ කුමක්ද?", "එක් අයෙකු හෝ ආයතනයක් අත බලය කේන්ද්‍රගත වී ඒකාධිපතිත්වයක් ඇති වීම වැළැක්වීම", "ආණ්ඩුවේ කටයුතු සම්පූර්ණයෙන් අඩපණ කිරීම", "මැතිවරණ පැවැත්වීම නතර කිරීම", "සියලු නීති අධිකරණයට පමණක් පැවරීම", "බලය විසින් බලය පාලනය කිරීමෙන් පුරවැසි නිදහස ආරක්ෂා වේ."),
    q("රටේ ප්‍රධාන නීති සම්පාදක ආයතනය හෙවත් ව්‍යවස්ථාදායකය වන්නේ කුමක්ද?", "ශ්‍රී ලංකා පාර්ලිමේන්තුව", "ශ්‍රේෂ්ඨාධිකරණය", "අමාත්‍ය මණ්ඩලය", "මැතිවරණ කොමිෂන් සභාව", "1978 ව්‍යවස්ථාව අනුව ව්‍යවස්ථාදායක බලය ජනතාව විසින් පාර්ලිමේන්තුව හරහා ක්‍රියාත්මක කෙරේ."),
    q("වර්තමාන ශ්‍රී ලංකා පාර්ලිමේන්තුවේ මුළු මන්ත්‍රීවරුන් සංඛ්‍යාව කීයද?", "225 දෙනෙකි", "196 දෙනෙකි", "250 දෙනෙකි", "101 දෙනෙකි", "දිස්ත්‍රික් මන්ත්‍රීවරුන් 196 ක් හා ජාතික ලැයිස්තු මන්ත්‍රීවරුන් 29 ක් ලෙස 225 දෙනෙකි."),
    q("ශ්‍රී ලංකා පාර්ලිමේන්තුවේ මැතිවරණ දිස්ත්‍රික්ක 22න් තේරී පත්වන මන්ත්‍රීවරුන් සංඛ්‍යාව කොපමණද?", "196 දෙනෙකි", "29 දෙනෙකි", "225 දෙනෙකි", "168 දෙනෙකි", "පාර්ලිමේන්තු මන්ත්‍රීවරුන් 225 අතරින් 196 දෙනෙකු දිස්ත්‍රික් මට්ටමින් තේරී පත්වේ."),
    q("ශ්‍රී ලංකා පාර්ලිමේන්තුවේ ජාතික ලැයිස්තුවෙන් පත්කරනු ලබන මන්ත්‍රීවරුන් සංඛ්‍යාව කීයද?", "29 දෙනෙකි", "19 දෙනෙකි", "35 දෙනෙකි", "15 දෙනෙකි", "පක්ෂ රට පුරා ලැබූ මුළු ඡන්ද අනුපාතය අනුව ජාතික ලැයිස්තු මන්ත්‍රීවරුන් 29 දෙනෙකු පත්වේ."),
    q("පාර්ලිමේන්තු රැස්වීම්වල මුලසුන හොබවන ප්‍රධාන නිලධාරියා කවුද?", "කථානායකවරයා", "අග්‍රාමාත්‍යවරයා", "විපක්ෂ නායකවරයා", "සභානායකවරයා", "පාර්ලිමේන්තුවේ විනය, විවාද හා ගෞරවය ආරක්ෂා කරන ප්‍රධානියා කථානායකවරයා වේ."),
    q("කථානායකවරයා නොමැති අවස්ථාවලදී පාර්ලිමේන්තු සභා රැස්වීම් මෙහෙයවීම සිදු කරන්නේ කවුද?", "නියෝජ්‍ය කථානායක හෝ කාරක සභා නියෝජ්‍ය සභාපති", "නීතිපතිවරයා", "මහ බැංකු අධිපති", "මැතිවරණ කොමසාරිස් ජනරාල්", "පාර්ලිමේන්තුව විසින් මන්ත්‍රීවරුන් අතරින් තෝරාපත් කරගන්නා නියෝජ්‍ය කථානායක මුලසුන ගනී."),
    q("පාර්ලිමේන්තුවේදී ආණ්ඩු පක්ෂයේ කටයුතු හා දෛනික න්‍යාය පත්‍රය සැලසුම් කර මෙහෙයවන ඇමතිවරයා කවුද?", "සභානායකවරයා", "විපක්ෂ නායකවරයා", "කථානායකවරයා", "පාර්ලිමේන්තු මහලේකම්", "ආණ්ඩුවේ ව්‍යවස්ථාදායක වැඩසටහන පාර්ලිමේන්තුව තුළ මෙහෙයවන්නේ සභානායකවරයාය."),
    q("පාර්ලිමේන්තුවේ විපක්ෂයේ සිටින ප්‍රධානතම පක්ෂයේ නායකයා කුමන තනතුරෙන් පිදුම් ලබයිද?", "විපක්ෂ නායක", "සභානායක", "ආණ්ඩු පක්ෂ ප්‍රධාන සංවිධායක", "නියෝජ්‍ය කථානායක", "ආණ්ඩුවේ වැරදි පෙන්වා දීමට හා විකල්ප අදහස් දැක්වීමට විපක්ෂ නායකවරයා ක්‍රියා කරයි."),
    q("පාර්ලිමේන්තු විවාදවලදී ආණ්ඩු පක්ෂ මන්ත්‍රීවරුන් සභාවට කැඳවීම හා ඡන්ද විමසීම් සම්බන්ධීකරණය කරන්නේ කවුද?", "ආණ්ඩු පක්ෂයේ ප්‍රධාන සංවිධායක", "පාර්ලිමේන්තු වේත්‍රධාරී", "ශ්‍රේෂ්ඨාධිකරණ රෙජිස්ට්‍රාර්", "විගණකාධිපතිවරයා", "Chief Government Whip හෙවත් ආණ්ඩු පක්ෂ ප්‍රධාන සංවිධායක පක්ෂ විනය හා කාලය සංවිධානය කරයි."),
    q("පාර්ලිමේන්තුවේ ආරක්ෂාව හා කථානායකවරයා පැමිණීමේදී සෙංකෝලය රැගෙන යන නිලධාරියා කවුද?", "වේත්‍රධාරී", "පාර්ලිමේන්තු මහලේකම්", "නියෝජ්‍ය කථානායක", "කාරක සභා ලේකම්", "Serjeant-at-Arms හෙවත් වේත්‍රධාරීවරයා පාර්ලිමේන්තුවේ උත්සව හා ආරක්ෂක කටයුතු ඉටු කරයි."),
    q("පාර්ලිමේන්තු සභා ගර්භයේ අධිකාරි බලය සංකේතවත් කරන වටිනා සංකේතය කුමක්ද?", "සෙංකෝලය", "ජාතික පුෂ්පය", "පුන්කලස", "අධිකරණ මුද්‍රාව", "සභා වාරය පවතින විට සෙංකෝලය සභා ගර්භයේ තැන්පත් කර තබනු ලැබේ."),
    q("පාර්ලිමේන්තුවේදී කෙරෙන සියලු කතා හා ක්‍රියාදාමයන් වචනයෙන් වචනය සටහන් කරන නිල වාර්තාව කුමක්ද?", "හංසඩ් වාර්තාව", "ගැසට් පත්‍රය", "විගණන වාර්තාව", "අයවැය ප්‍රකාශනය", "හංසඩ් (Hansard) වාර්තාව පාර්ලිමේන්තුවේ නිල වාර්තාව ලෙස ප්‍රකාශයට පත් කෙරේ."),
    q("නව නීතියක් පැනවීම සඳහා පාර්ලිමේන්තුවට ඉදිරිපත් කරන මුල් කෙටුම්පත හඳුන්වනු ලබන්නේ කුමන නමින්ද?", "පනත් කෙටුම්පතක්", "පාර්ලිමේන්තු පනතක්", "ගැසට් නිවේදනයක්", "චක්‍රලේඛයක්", "පාර්ලිමේන්තුව සම්මත කර කථානායක සහතික කරන තුරු එය පනත් කෙටුම්පතක් (Bill) ලෙස හැඳින්වේ."),
    q("පනත් කෙටුම්පතක් පාර්ලිමේන්තුවේ සම්මත වී කථානායකවරයාගේ සහතිකය සටහන් කළ පසු එය හඳුන්වන්නේ කුමන නමින්ද?", "පාර්ලිමේන්තු පනතක්", "කෙටුම්පත් යෝජනාවක්", "අමාත්‍යාංශ වාර්තාවක්", "පළාත් ප්‍රඥප්තියක්", "79 වන වගන්තිය අනුව කථානායක සහතිකයත් සමඟ එය නීත්‍යානුකූල පනතක් (Act) බවට පත්වේ."),
    q("පනත් කෙටුම්පතක මූලික ප්‍රතිපත්ති පිළිබඳව පාර්ලිමේන්තුවේ පුළුල් විවාදය හා ඡන්ද විමසීම සිදුවන්නේ කවර අදියරේදීද?", "දෙවන කියවීමේදී", "පළමු කියවීමේදී", "ගැසට් පළකිරීමේදී", "නඩු විභාගයේදී", "දෙවන කියවීමේදී පනතේ මූලික හරය හා අවශ්‍යතාව විවාදයට ගැනේ."),
    q("පනත් කෙටුම්පතක වගන්තියෙන් වගන්තිය පරීක්ෂා කර සංශෝධන ඇතුළත් කරනු ලබන්නේ කුමන අවස්ථාවේදීද?", "කාරක සභා අවස්ථාවේදී", "පළමු කියවීමේදී", "තෙවන කියවීමේදී", "සහතික කිරීමේ අවස්ථාවේදී", "දෙවන කියවීමෙන් පසු කාරක සභා අවස්ථාවේදී එක් එක් වගන්තිය සවිස්තරව සංශෝධනය කෙරේ."),
    q("පනත් කෙටුම්පතක් පාර්ලිමේන්තුවට ඉදිරිපත් කිරීමට අවම වශයෙන් දින කීයකට පෙර රජයේ ගැසට් පත්‍රයේ පළ කළ යුතුද?", "දින 7 කට පෙර", "දින 90 කට පෙර", "වසර 1 කට පෙර", "දින 1 කට පෙර", "78(1) වගන්තිය අනුව පනත් කෙටුම්පතක් න්‍යාය පත්‍රයට ගැනීමට අවම දින 7 කට පෙර ගැසට් කළ යුතුය."),
    q("ශ්‍රී ලංකාවේ රාජ්‍ය මූල්‍ය පිළිබඳ සම්පූර්ණ පාලන බලය ව්‍යවස්ථාවේ 148 වගන්තියෙන් පැවරී ඇත්තේ කුමන ආයතනයටද?", "පාර්ලිමේන්තුවට", "ශ්‍රේෂ්ඨාධිකරණයට", "මැතිවරණ කොමිසමට", "විදේශ අමාත්‍යාංශයට", "පාර්ලිමේන්තු අනුමැතියකින් තොරව බදු පැනවීමට හෝ රාජ්‍ය අරමුදල් වැය කිරීමට නොහැක."),
    q("රජයේ වාර්ෂික ආදායම් සහ වියදම් ඇස්තමේන්තු ඇතුළත් කොට පාර්ලිමේන්තුවට ඉදිරිපත් කරන ප්‍රධාන පනත් කෙටුම්පත කුමක්ද?", "විසර්ජන පනත් කෙටුම්පත", "අල්ලස් පනත් කෙටුම්පත", "රාජ්‍ය සේවා පනත", "පළාත් පාලන ආඥා පනත", "වාර්ෂික අයවැය ලේඛනය නීතිගත කිරීම සඳහා විසර්ජන පනත් කෙටුම්පත (Appropriation Bill) ගෙන එනු ලැබේ."),
    q("රාජ්‍ය සංස්ථා, ව්‍යවස්ථාපිත මණ්ඩල හා රජයට අයත් සමාගම්වල මූල්‍ය කටයුතු විමර්ශනය කරන පාර්ලිමේන්තු කමිටුව කුමක්ද?", "කෝප් කමිටුව", "මැතිවරණ කමිටුව", "සමථ කමිටුව", "අධිකරණ කමිටුව", "පොදු ව්‍යාපාර පිළිබඳ කාරක සභාව (COPE) රාජ්‍ය ව්‍යවසායවල මූල්‍ය විනය විමර්ශනය කරයි."),
    q("රජයේ අමාත්‍යාංශ, දෙපාර්තමේන්තු හා පළාත් පාලන ආයතනවල රාජ්‍ය ගිණුම් පරීක්ෂා කරන පාර්ලිමේන්තු කාරක සභාව කුමක්ද?", "කෝපා කමිටුව", "ආරක්ෂක කමිටුව", "ප්‍රසම්පාදන කමිටුව", "තොරතුරු කමිටුව", "රජයේ ගිණුම් පිළිබඳ කාරක සභාව (COPA) රාජ්‍ය දෙපාර්තමේන්තුවල වියදම් විගණනය පරීක්ෂා කරයි."),
    q("රාජ්‍ය මූල්‍ය හා බදු ප්‍රතිපත්ති පිළිබඳව පාර්ලිමේන්තුවට වාර්තා කරන විශේෂ කමිටුව කුමක්ද?", "රජයේ මුදල් පිළිබඳ කාරක සභාව", "ළමා ආරක්ෂක කමිටුව", "ක්‍රීඩා උපදේශක කමිටුව", "විදේශ රැකියා කමිටුව", "Committee on Public Finance (COPF) අයවැය හා බදු කෙටුම්පත් පරීක්ෂා කරයි."),
    q("රජයේ සියලුම ආයතනවල මූල්‍ය ගිණුම් ස්වාධීනව විගණනය කර පාර්ලිමේන්තුවට වාර්තා කරන නිලධාරියා කවුද?", "විගණකාධිපතිවරයා", "වේත්‍රධාරීවරයා", "ප්‍රාදේශීය ලේකම්වරයා", "රේගු අධ්‍යක්ෂ ජනරාල්", "විගණකාධිපතිවරයා පාර්ලිමේන්තුව වෙනුවෙන් රාජ්‍ය මූල්‍ය විනය පරීක්ෂා කරයි."),
    q("පාර්ලිමේන්තු සභා ගර්භය තුළදී මන්ත්‍රීවරුන් පළ කරන අදහස්වලට අධිකරණයක නඩු පැවරීමෙන් ආරක්ෂාව සැලසෙන්නේ කුමන වරප්‍රසාදය යටතේද?", "පාර්ලිමේන්තු භාෂණ නිදහස හා වරප්‍රසාද", "රාජ්‍ය තාන්ත්‍රික වීසා", "කැබිනට් සාමූහිකත්වය", "හදිසි නීති ආඥාව", "බලපෑමකින් තොරව ජනතා ප්‍රශ්න හෙළි කිරීමට පාර්ලිමේන්තු වරප්‍රසාද පනතින් රැකවරණය සැලසේ."),
    q("ශ්‍රී ලංකාවේ විධායක ජනාධිපතිවරයා තෝරාපත් කරගනු ලබන්නේ කවර ආකාරයකින්ද?", "මුළු රටම එක් ඡන්ද කොට්ඨාසයක් ලෙස සලකා මහජන ඡන්දයෙන්", "පාර්ලිමේන්තු මන්ත්‍රීවරුන්ගේ රහස් ඡන්දයෙන් පමණක්", "ශ්‍රේෂ්ඨාධිකරණ විනිසුරුවරුන්ගේ අනුමැතියෙන්", "පළාත් සභා ආණ්ඩුකාරවරුන්ගේ ඡන්දයෙන්", "ජනාධිපතිවරණයකදී රටේ සියලුම ලියාපදිංචි ඡන්දදායකයන්ගේ සෘජු ඡන්දයෙන් තේරී පත්වේ."),
    q("වත්මන් 19 වන හා 21 වන සංශෝධන අනුව ශ්‍රී ලංකාවේ විධායක ජනාධිපතිවරයෙකුගේ නිල කාලය වසර කීයක්ද?", "වසර 5 කි", "වසර 6 කි", "වසර 4 කි", "වසර 7 කි", "19 වන සංශෝධනයෙන් පසු ජනාධිපති ධුර කාලය වසර 5ක් වේ."),
    q("එක් පුද්ගලයෙකුට ශ්‍රී ලංකාවේ විධායක ජනාධිපති ධුරයට පත්විය හැකි උපරිම වාර ගණන කීයද?", "දෙවරකි", "එක් වරකි", "තුන් වරකි", "සීමාවක් නැත", "31(2) වගන්තිය අනුව දෙවරකට වඩා ජනාධිපති ධුරයට තේරී පත්විය නොහැක."),
    q("ශ්‍රී ලංකාවේ ත්‍රිවිධ හමුදාවේ සේනාධිනායකයා ලෙස ව්‍යවස්ථාවෙන් නම් කර ඇත්තේ කවුද?", "විධායක ජනාධිපතිවරයා", "අග්‍රාමාත්‍යවරයා", "කථානායකවරයා", "අගවිනිසුරුවරයා", "30(1) වගන්තිය අනුව ජනාධිපතිවරයා සන්නද්ධ සේවාවන්ගේ සේනාධිනායකයා වේ."),
    q("හදිසි අවස්ථාවකදී ජනාධිපතිවරයා විසින් හදිසි නීති ප්‍රකාශනයක් නිකුත් කළ විට එය දින කීයක් ඇතුළත පාර්ලිමේන්තුවට ඉදිරිපත් කර අනුමත කරගත යුතුද?", "දින 14 ක් ඇතුළත", "දින 90 ක් ඇතුළත", "වසර 1 ක් ඇතුළත", "දින 365 ක් ඇතුළත", "මහජන ආරක්ෂක පනත යටතේ පාර්ලිමේන්තු අනුමැතිය නොලැබුණහොත් හදිසි නීතිය අහෝසි වේ."),
    q("අධිකරණයකින් වරදකරුවෙකු කරන ලද අයෙකුට ජනාධිපති සමාව දීමේ බලය ජනාධිපතිවරයාට හිමිවන්නේ කුමන වගන්තිය යටතේද?", "34 වන වගන්තිය", "12 වන වගන්තිය", "28 වන වගන්තිය", "148 වන වගන්තිය", "34 වන වගන්තිය අනුව නියමිත ක්‍රමවේදය අනුගමනය කර ජනාධිපති සමාව ප්‍රදානය කළ හැක."),
    q("විධායක ජනාධිපතිවරයෙකු ව්‍යවස්ථාව උල්ලංඝනය කළහොත් ඔහු ධුරයෙන් ඉවත් කිරීම සඳහා පාර්ලිමේන්තුවේ ගෙන එන ක්‍රියාවලිය කුමක්ද?", "දෝෂාභියෝග යෝජනාව", "අයවැය කප්පාදුව", "සාමාන්‍ය විශ්වාසභංග යෝජනාව", "අතුරු මැතිවරණය", "38(2) වගන්තිය අනුව 2/3 ක යෝජනාව, ශ්‍රේෂ්ඨාධිකරණ විමර්ශනය හා 2/3 ක අවසන් ඡන්දයෙන් දෝෂාභියෝගය ක්‍රියාත්මක වේ."),
    q("ජනාධිපතිවරයෙකුට එරෙහි දෝෂාභියෝග යෝජනාවක ඇති චෝදනා පිළිබඳව විභාග කර වාර්තා කිරීමේ බලය ඇත්තේ කුමන ආයතනයටද?", "ශ්‍රේෂ්ඨාධිකරණයට", "අභියාචනාධිකරණයට", "මැතිවරණ කොමිසමට", "මහාධිකරණයට", "කථානායක විසින් දෝෂාභියෝග චෝදනා විමර්ශනය සඳහා ශ්‍රේෂ්ඨාධිකරණය වෙත යොමු කරනු ලැබේ."),
    q("ජනාධිපති ධුරය හදිසියේ හිස් වුවහොත් ඉතිරි ධුර කාලය සඳහා මාසයක් ඇතුළත නව ජනාධිපතිවරයෙකු තෝරාපත් කරගන්නේ කවුරුන් විසින්ද?", "පාර්ලිමේන්තුව විසින්", "අමාත්‍යාංශ ලේකම්වරුන් විසින්", "පළාත් සභා සභාපතිවරුන් විසින්", "අධිකරණ සේවා කොමිසම විසින්", "40 වන වගන්තිය අනුව ඉතිරි කාලය සඳහා පාර්ලිමේන්තු මන්ත්‍රීවරුන්ගේ රහස් ඡන්දයෙන් ජනාධිපතිවරයෙකු පත් කරයි."),
    q("ජනාධිපති ධුරය හිස් වූ අවස්ථාවේ සිට නව ජනාධිපතිවරයෙකු පත්වන තුරු වැඩබලන ජනාධිපති ලෙස ක්‍රියා කරන්නේ කවුද?", "අග්‍රාමාත්‍යවරයා", "විපක්ෂ නායකවරයා", "විගණකාධිපතිවරයා", "කොළඹ නගරාධිපති", "අග්‍රාමාත්‍යවරයා (හෝ ඔහු නොමැති නම් කථානායකවරයා) වැඩබලන ජනාධිපති ලෙස කටයුතු කරයි."),
    q("ජනාධිපතිවරයා විසින් අග්‍රාමාත්‍යවරයා ලෙස පත් කරනු ලබන්නේ කවර මන්ත්‍රීවරයෙකුද?", "පාර්ලිමේන්තුවේ විශ්වාසය උපරිමයෙන් දිනාගත හැකි යැයි ජනාධිපතිවරයා සලකන මන්ත්‍රීවරයා", "වැඩිම වයස්ගතම මන්ත්‍රීවරයා", "ජාතික ලැයිස්තුවේ අවසාන නම ඇති මන්ත්‍රීවරයා", "විපක්ෂයේ පරාජිත අපේක්ෂකයෙකු", "පාර්ලිමේන්තු බහුතර විශ්වාසය ඇති මන්ත්‍රීවරයා අගමැති ධුරයට පත් කෙරේ."),
    q("රජයේ ප්‍රතිපත්ති තීරණ ගන්නා ඉහළම විධායක ආයතනය වන 'අමාත්‍ය මණ්ඩලය' වගකිව යුත්තේ කුමන ආයතනයටද?", "පාර්ලිමේන්තුවට", "ශ්‍රේෂ්ඨාධිකරණයට", "රාජ්‍ය බැංකු සංගමයට", "තානාපති කාර්යාලවලට", "කැබිනට් මණ්ඩලය සිය පාලනය හා තීරණ සඳහා පාර්ලිමේන්තුවට සාමූහිකව වගකිව යුතුය."),
    q("අමාත්‍ය මණ්ඩලයේ කැබිනට් අමාත්‍යවරුන් පත් කිරීමේදී ජනාධිපතිවරයා විමසා උපදෙස් ලබාගත යුත්තේ කාගෙන්ද?", "අග්‍රාමාත්‍යවරයාගෙන්", "අගවිනිසුරුවරයාගෙන්", "මැතිවරණ කොමිසමෙන්", "පොලිස්පතිවරයාගෙන්", "විෂයයන් බෙදා වෙන් කිරීම හා කැබිනට් අමාත්‍යවරුන් පත් කිරීම අගමැතිගේ උපදෙස් මත සිදු කෙරේ."),
    q("රජයේ එක් එක් අමාත්‍යාංශයේ ප්‍රධාන පරිපාලන හා ගණන් දීමේ නිලධාරියා කවුද?", "අමාත්‍යාංශ ලේකම්වරයා", "පාර්ලිමේන්තු කථානායක", "පළාත් ආණ්ඩුකාරවරයා", "දිසා විනිසුරුවරයා", "අමාත්‍යාංශ ලේකම්වරයා අමාත්‍යාංශයේ පරිපාලන ප්‍රධානියා හා ප්‍රධාන ගණන් දීමේ නිලධාරියා වේ."),
    q("ශ්‍රී ලංකාවේ පොදු නීතිය (Common Law) හෙවත් ප්‍රධාන සිවිල් නීති පද්ධතිය ලෙස සැලකෙන්නේ කුමක්ද?", "රෝම-ලන්දේසි නීතිය", "උඩරට නීතිය", "තේසවලාමෙයි නීතිය", "මුස්ලිම් නීතිය", "ලන්දේසි පාලන යුගයෙන් මෙරටට උරුම වූ රෝම-ලන්දේසි නීතිය ශ්‍රී ලංකාවේ පොදු නීතියයි."),
    q("ශ්‍රී ලංකාවේ අපරාධ නීතිය සහ වාණිජ නීතිය සඳහා මූලික වශයෙන් පදනම් වී ඇති නීති පද්ධතිය කුමක්ද?", "ඉංග්‍රීසි නීතිය", "රෝම-ලන්දේසි නීතිය", "උඩරට නීතිය", "තේසවලාමෙයි නීතිය", "දණ්ඩ නීති සංග්‍රහය, සමාගම් නීතිය හා බැංකු නීතිය ඉංග්‍රීසි නීතිය මත ගොඩනැගී ඇත."),
    q("යාපනය අර්ධද්වීපයේ පදිංචි දෙමළ ජනතාවගේ දේපළ හා පවුල් සබඳතා සඳහා බලපාන විශේෂ නීතිය කුමක්ද?", "තේසවලාමෙයි නීතිය", "උඩරට නීතිය", "රෝම-ලන්දේසි නීතිය", "ඉංග්‍රීසි නීතිය", "යාපනයේ මලබාර් ජනතාවගේ සිරිත් විරිත් අනුව ලන්දේසීන් තේසවලාමෙයි නීතිය සංග්‍රහ කළේය."),
    q("උඩරට සිංහල ප්‍රජාවගේ විවාහ, දික්කසාද හා දේපළ උරුමය සම්බන්ධයෙන් අදාළ වන විශේෂ නීතිය කුමක්ද?", "උඩරට නීතිය", "තේසවලාමෙයි නීතිය", "මුස්ලිම් නීතිය", "සමුද්‍රීය නීතිය", "මහනුවර රාජධානියට අයත්ව තිබූ ප්‍රදේශවල උඩරට සිංහලයන්ට උඩරට නීතිය බලපායි."),
    q("ඉස්ලාම් භක්තිකයන්ගේ විවාහ, දික්කසාද හා උරුම කටයුතු සම්බන්ධයෙන් ක්‍රියාත්මක වන පෞද්ගලික නීතිය කුමක්ද?", "මුස්ලිම් නීතිය", "උඩරට නීතිය", "රෝම-ලන්දේසි නීතිය", "තේසවලාමෙයි නීතිය", "පුද්ගල පදනමින් සියලුම ශ්‍රී ලාංකික මුස්ලිම්වරුන්ට මුස්ලිම් නීතිය අදාළ වේ."),
    q("ශ්‍රී ලංකාවේ අධිකරණ ධූරාවලියේ ඉහළම සහ අවසන් අධිකරණය වන්නේ කුමක්ද?", "ශ්‍රේෂ්ඨාධිකරණය", "අභියාචනාධිකරණය", "මහාධිකරණය", "දිසා අධිකරණය", "ශ්‍රේෂ්ඨාධිකරණය රටේ උත්තරීතරම අධිකරණය වන අතර එහි තීන්දු අවසානාත්මක වේ."),
    q("ව්‍යවස්ථාව අර්ථනිරූපණය කිරීමේ හා මූලික අයිතිවාසිකම් නඩු විභාග කිරීමේ තනි බලය හිමිවන්නේ කුමන අධිකරණයටද?", "ශ්‍රේෂ්ඨාධිකරණයට", "මහේස්ත්‍රාත් අධිකරණයට", "දිසා අධිකරණයට", "කම්කරු විනිශ්චය සභාවට", "118 හා 125–126 වගන්ති අනුව මෙම බලතල ශ්‍රේෂ්ඨාධිකරණයට පමණක් හිමිවේ."),
    q("මහේස්ත්‍රාත් හා දිසා අධිකරණ තීන්දුවලට එරෙහිව පළමු අභියාචනා ඉදිරිපත් කරන ප්‍රධාන උපරිමාධිකරණය කුමක්ද?", "අභියාචනාධිකරණය", "ප්‍රාථමික අධිකරණය", "සමථ මණ්ඩලය", "කම්කරු විනිශ්චය සභාව", "ශ්‍රේෂ්ඨාධිකරණයට පහළින් පිහිටි ප්‍රධාන අභියාචනා ආයතනය අභියාචනාධිකරණයයි."),
    q("බරපතළ අපරාධ නඩු (මිනීමැරුම්, මංකොල්ලකෑම් වැනි) මුලින්ම විභාග කරන මුල් අවස්ථා අධිකරණය කුමක්ද?", "මහාධිකරණය", "ප්‍රාථමික අධිකරණය", "දිසා අධිකරණය", "මහේස්ත්‍රාත් අධිකරණය", "මහාධිකරණය බරපතළ අපරාධ නඩු ජූරි සභාවක් සහිතව හෝ රහිතව විභාග කරයි."),
    q("ප්‍රධාන වශයෙන් සිවිල් නඩු (ඉඩම්, දේපළ, ණය, පවුල් ආරවුල්) විභාග කරන මුල් අවස්ථා අධිකරණය කුමක්ද?", "දිසා අධිකරණය", "මහේස්ත්‍රාත් අධිකරණය", "සමථ මණ්ඩලය", "විශේෂ මහාධිකරණය", "දිසා අධිකරණය සිවිල් ආරවුල් හා වන්දි ඉල්ලීම් පිළිබඳ මුල් අවස්ථා අධිකරණයයි."),
    q("සුළු අපරාධ නඩු විභාග කිරීම සහ බරපතළ අපරාධ නඩුවල මූලික පරීක්ෂණ පැවැත්වීම සිදු කරන අධිකරණය කුමක්ද?", "මහේස්ත්‍රාත් අධිකරණය", "ශ්‍රේෂ්ඨාධිකරණය", "අභියාචනාධිකරණය", "පළාත් සිවිල් අභියාචනා මහාධිකරණය", "මහේස්ත්‍රාත් අධිකරණය ලඝු නඩු විභාග හා සෝදිසි වරෙන්තු නිකුත් කිරීම ඉටු කරයි."),
    q("සේවකයන් හා සේවායෝජකයන් අතර ඇතිවන රැකියා ආරවුල් විසඳීම සඳහා පිහිටුවා ඇති විශේෂිත ආයතනය කුමක්ද?", "කම්කරු විනිශ්චය සභාව", "පළාත් මහාධිකරණය", "වෙළඳ මණ්ඩලය", "රාජ්‍ය සේවා කොමිසම", "අසාධාරණ ලෙස සේවයෙන් පහ කිරීම වැනි කම්කරු ගැටලු කම්කරු විනිශ්චය සභාවෙන් විභාග කෙරේ."),
    q("විනිසුරුවරුන්ගේ වැටුප් අඩු කිරීම හෝ ඔවුන් හිතුමතේ සේවයෙන් ඉවත් කිරීම තහනම් කර ඇත්තේ කුමක් ආරක්ෂා කිරීමටද?", "අධිකරණයේ ස්වාධීනත්වය", "විධායකයේ උත්තරීතරභාවය", "පාර්ලිමේන්තු ඒකාධිකාරය", "පළාත් සභා ආදායම", "විධායක හා දේශපාලන බලපෑම්වලින් තොරව යුක්තිය පසිඳලීමට අධිකරණ ස්වාධීනත්වය අත්‍යවශ්‍ය වේ."),
    q("රජයේ ප්‍රධාන නීති උපදේශකවරයා සහ අපරාධ නඩු පවරන ප්‍රධාන රාජ්‍ය නිලධාරියා කවුද?", "නීතිපතිවරයා", "අගවිනිසුරුවරයා", "විගණකාධිපතිවරයා", "ඔම්බුඩ්ස්මන්වරයා", "නීතිපතිවරයා රජය වෙනුවෙන් අධිකරණය හමුවේ පෙනී සිටින ප්‍රධාන නීතිඥවරයා වේ."),
    q("ව්‍යවස්ථාදායකය විසින් විධායකය පාලනය කරනු ලබන ප්‍රධාන පාර්ලිමේන්තු උපකරණයක් වන්නේ කුමක්ද?", "විශ්වාසභංග යෝජනා සහ අයවැය විවාද", "හදිසි නීති පැනවීම", "ජනාධිපති සමාව ප්‍රදානය", "අධිකරණ වරෙන්තු නිකුත් කිරීම", "ප්‍රශ්න ඇසීම, අයවැය පාලනය හා විශ්වාසභංග යෝජනා මඟින් පාර්ලිමේන්තුව විධායකය පාලනය කරයි."),
    q("පාර්ලිමේන්තු කටයුතු පරිපාලනය හා නීතිමය උපදෙස් ලබාදෙන ස්ථිර ප්‍රධාන නිලධාරියා කවුද?", "පාර්ලිමේන්තුවේ මහලේකම්වරයා", "විපක්ෂ නායකවරයා", "කැබිනට් ප්‍රකාශකවරයා", "දිසාපතිවරයා", "පාර්ලිමේන්තු මහලේකම්වරයා කථානායකවරයාට පාර්ලිමේන්තු පරිපාලනයේදී සහාය වේ."),
    q("ශ්‍රේෂ්ඨාධිකරණය විසින් නඩු තීන්දුවක් ලබා දෙන විට ප්‍රධානියා ලෙස ක්‍රියා කරන උසස්ම විනිසුරුවරයා කවුද?", "අගවිනිසුරුවරයා", "මහේස්ත්‍රාත්වරයා", "නීතිපතිවරයා", "සොලිසිටර් ජනරාල්වරයා", "ශ්‍රේෂ්ඨාධිකරණයේ ප්‍රධානියා අග්‍රවිනිශ්චයකාරවරයා (Chief Justice) වේ."),
    q("රටේ සියලුම පුරවැසියන්ට හා රජයට නීතිය ඉදිරියේ එක හා සමානව සැලකීමේ මූලධර්මය කුමක්ද?", "නීතියේ ආධිපත්‍යය", "පාර්ලිමේන්තු වරප්‍රසාදය", "රාජ්‍ය මුක්තිය", "නිෂේධ බලය", "කිසිවෙකු නීතියට ඉහළින් නොසිටීම නීතියේ ආධිපත්‍යයයි."),
    q("අධිකරණයේ සහ විධායකයේ හා ව්‍යවස්ථාදායකයේ කාර්යයන් එකිනෙක පාලනය කරමින් සමබරතාව රැකීමේ ක්‍රමය කුමක්ද?", "තුලන හා සංවරණ ක්‍රමය", "ඒකාධිපති මධ්‍යගතකරණය", "වැඩවසම් රාජකාරි ක්‍රමය", "නිලලත් නියෝජනය", "එක් අංශයක් සතු අසීමිත බලය අනෙක් අංශ මඟින් පාලනය කිරීම Checks and Balances වේ."),
    q("විධායක ජනාධිපතිවරයෙකු සිය නිල කටයුතු ඉටු කිරීමේදී පෞද්ගලිකව නඩු පැවරීමෙන් ආරක්ෂා වන නෛතික ප්‍රතිපාදනය කුමක්ද?", "ජනාධිපති මුක්තිය", "පාර්ලිමේන්තු ස්ථාවර නියෝග", "අමාත්‍ය මණ්ඩල රහස්‍යභාවය", "සමථ මණ්ඩල වරප්‍රසාදය", "ව්‍යවස්ථාවේ 35 වන වගන්තියෙන් ජනාධිපති මුක්තිය පිළිබඳ දැක්වේ."),
    q("ව්‍යවස්ථාවේ 19 හා 21 සංශෝධන අනුව ජනාධිපතිවරයාගේ නිල ක්‍රියාවකින් මූලික අයිතිවාසිකමක් කඩවුවහොත් කාට එරෙහිව නඩු පැවරිය හැකිද?", "නීතිපතිවරයාට එරෙහිව", "කථානායකවරයාට එරෙහිව", "විගණකාධිපතිවරයාට එරෙහිව", "පොලිස්පතිවරයාට පමණක්", "35 වන වගන්තියේ සංශෝධනය අනුව ජනාධිපතිවරයාගේ නිල ක්‍රියාවකට නීතිපති නම් කර නඩු පැවරිය හැක."),
    q("කැබිනට් මණ්ඩලයට අයත් නොවන නමුත් විශේෂ විෂය පථයන් භාරව ජනාධිපතිවරයා විසින් පත් කරන අමාත්‍යවරුන් කවුද?", "කැබිනට් නොවන සහ රාජ්‍ය අමාත්‍යවරුන්", "සෙනෙට් සභිකයන්", "පළාත් ආණ්ඩුකාරවරුන්", "නාගරික කොමසාරිස්වරුන්", "44 හා 45 වගන්ති යටතේ කැබිනට් නොවන හා නියෝජ්‍ය අමාත්‍යවරුන් පත් කරනු ලැබේ."),
    q("පාර්ලිමේන්තුවේදී යම් පනත් කෙටුම්පතක් 'පළමු කියවීම' ලෙස හැඳින්වෙන්නේ කුමන පියවරද?", "කෙටුම්පතේ නාමය සභාවට ඉදිරිපත් කර මුද්‍රණයට නියම කිරීම", "පනතට ජනමත විචාරණයක් පැවැත්වීම", "කථානායකවරයා අවසන් සහතිකය අත්සන් කිරීම", "වගන්ති සියල්ල විවාද කර සංශෝධනය කිරීම", "පළමු කියවීමේදී විවාදයක් නොමැතිව කෙටුම්පත සභාවට ඉදිරිපත් කරයි."),
    q("පාර්ලිමේන්තුවේ 'තෙවන කියවීම' අවස්ථාවේදී සිදු කෙරෙන්නේ කුමක්ද?", "සංශෝධන සහිත සම්පූර්ණ කෙටුම්පත අවසන් වශයෙන් සම්මත කරගැනීම", "කෙටුම්පත ගැසට් පත්‍රයේ ප්‍රථම වරට පළ කිරීම", "ජනාධිපතිවරයා අමාත්‍ය මණ්ඩලය විසුරුවා හැරීම", "ශ්‍රේෂ්ඨාධිකරණයට පෙත්සම් බාරදීම", "කාරක සභා අවස්ථාවෙන් පසු තෙවන කියවීමෙන් කෙටුම්පත සම්මත කෙරේ."),
    q("පාර්ලිමේන්තු වාර්ෂික අයවැය විවාදය පරාජය වුවහොත් ආණ්ඩුක්‍රම ව්‍යවස්ථාව අනුව කැබිනට් මණ්ඩලයට කුමක් සිදුවේද?", "අග්‍රාමාත්‍යවරයා ප්‍රමුඛ කැබිනට් මණ්ඩලය විසුරුවී යයි", "පාර්ලිමේන්තුවේ මන්ත්‍රී සංඛ්‍යාව අඩු වේ", "අගවිනිසුරුවරයා අයවැය ඉදිරිපත් කරයි", "පළාත් සභා සියල්ල අහෝසි වේ", "විසර්ජන පනත් කෙටුම්පත දෙවන වරටත් හෝ අයවැය ප්‍රතික්ෂේප වීමෙන් ආණ්ඩුවට බහුතර විශ්වාසය අහිමි වේ."),
    q("රටේ පරිපාලන අධිකරණ බලතල හා රිට් ආඥා (Writ Orders) නිකුත් කිරීමේ මූලික අධිකරණ බලය හිමිවන්නේ කුමන අධිකරණයටද?", "අභියාචනාධිකරණයට", "මහේස්ත්‍රාත් අධිකරණයට", "දිසා අධිකරණයට", "සමථ මණ්ඩලයට", "140 වන වගන්තිය අනුව සර්ටියෝරාරි, මැන්ඩමුස් වැනි රිට් ආඥා නිකුත් කිරීමේ බලය අභියාචනාධිකරණයට හිමිවේ."),
    q("පුද්ගලයෙකු නීති විරෝධී ලෙස රඳවා තබාගෙන සිටින විට ඔහු අධිකරණයට ඉදිරිපත් කරන ලෙස නියෝග කරන රිට් ආඥාව කුමක්ද?", "හබයාස් කෝපස් ආඥාව", "කුවෝ වොරන්ටෝ ආඥාව", "තහනම් ආඥාව", "සර්ටියෝරාරි ආඥාව", "141 වන වගන්තිය අනුව නීති විරෝධී රඳවා ගැනීමකදී Habeas Corpus රිට් ආඥාව ඉල්ලා සිටිය හැක."),
    q("මහේස්ත්‍රාත් හා දිසා විනිසුරුවරුන් පත් කිරීම, මාරු කිරීම හා විනය පාලනය සිදු කරන ආයතනය කුමක්ද?", "අධිකරණ සේවා කොමිෂන් සභාව", "රාජ්‍ය සේවා කොමිෂන් සභාව", "පාර්ලිමේන්තු මහලේකම් කාර්යාලය", "නීතිපති දෙපාර්තමේන්තුව", "අගවිනිසුරු හා ශ්‍රේෂ්ඨාධිකරණ විනිසුරුවරුන් දෙදෙනෙකුගෙන් යුත් අධිකරණ සේවා කොමිසම මෙය ඉටු කරයි."),
